class Dog:
    def __init__(self, human_age):
        self.human_age = human_age

    def calculate_dog_years(self):
        if self.human_age <= 0:
            return "Invalid age. Please provide a valid human age."
        elif self.human_age <= 2:
            dog_years = self.human_age * 10.5
        else:
            dog_years = 2 * 10.5 + (self.human_age - 2) * 4
