```python
def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_primes(limit):
    primes = []
    for num in range(2, limit):
        if is_prime(num):
            primes.append(num)
    return primes

limit = 100  # Change this to generate primes up to a different limit
prime_numbers = generate_primes(limit)
print(prime_numbers)
```

